import { LinearGradient } from "expo-linear-gradient";
import type { ReactNode } from "react";
import { Image, Pressable, StyleSheet, Text, View, type ImageSourcePropType } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { serif, wood } from "@/lib/theme";

// Tileable grain overlays, generated by scripts/make-textures.py.
export const WOOD_UPRIGHT = require("@/assets/textures/wood-v.png");
export const WOOD_ACROSS = require("@/assets/textures/wood-h.png");

/** A repeating grain image laid over whatever colour is underneath. */
export function Grain({ source, opacity }: { source: ImageSourcePropType; opacity: number }) {
  return <Image source={source} resizeMode="repeat" style={[styles.grain, { opacity }]} />;
}

/** The wooden bar across the top of a screen, clear of the phone's status bar. */
export function WoodBar({ title, left, right }: { title: string; left?: ReactNode; right?: ReactNode }) {
  const insets = useSafeAreaInsets();
  return (
    <LinearGradient colors={wood.bar} style={[styles.bar, { paddingTop: insets.top + 8 }]}>
      <Grain source={WOOD_ACROSS} opacity={0.4} />
      <View style={styles.side}>{left}</View>
      <Text style={styles.title} numberOfLines={1}>
        {title}
      </Text>
      <View style={[styles.side, styles.right]}>{right}</View>
    </LinearGradient>
  );
}

export function WoodButton({ label, onPress }: { label: string; onPress: () => void }) {
  return (
    <Pressable onPress={onPress} style={({ pressed }) => [styles.button, pressed && styles.buttonPressed]}>
      <Text style={styles.buttonText}>{label}</Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  grain: { position: "absolute", top: 0, left: 0, width: "100%", height: "100%" },
  bar: {
    flexDirection: "row", alignItems: "center", paddingHorizontal: 10, paddingBottom: 8,
    borderBottomWidth: 2, borderColor: wood.edge, boxShadow: "0 4px 10px rgba(0,0,0,0.6)", zIndex: 2,
  },
  side: { flex: 1, flexDirection: "row" },
  right: { justifyContent: "flex-end" },
  title: { fontFamily: serif, fontSize: 20, fontWeight: "bold", color: wood.ink, textShadowColor: "rgba(0,0,0,0.6)", textShadowOffset: { width: 0, height: 1 }, textShadowRadius: 2 },
  button: { paddingHorizontal: 12, paddingVertical: 7, borderRadius: 6, borderWidth: 1, borderColor: wood.edge, backgroundColor: wood.button, boxShadow: "inset 0 1px 0 rgba(255,255,255,0.18), 0 1px 2px rgba(0,0,0,0.5)" },
  buttonPressed: { backgroundColor: wood.buttonPressed },
  buttonText: { fontFamily: serif, fontSize: 13, fontWeight: "bold", color: wood.ink },
});
